package org.signal.benchmark.waveform;

import android.app.Activity;
import android.content.Context;
import android.graphics.Canvas;
import android.graphics.Color;
import android.graphics.Paint;
import android.os.Bundle;
import android.view.View;
import android.widget.Button;
import android.widget.LinearLayout;
import android.widget.TextView;
import org.json.JSONArray;
import org.json.JSONException;
import org.json.JSONObject;

/** Page that hosts the voice note waveform pipeline. */
public final class VoiceWaveformActivity extends Activity {
  private WaveformPageOwner owner;
  private TextView status;
  private WaveformBarsView waveformView;

  @Override public void onCreate(Bundle state) {
    super.onCreate(state);
    owner = new WaveformPageOwner(this);
    LinearLayout page = new LinearLayout(this);
    page.setOrientation(LinearLayout.VERTICAL);
    page.setPadding(32, 32, 32, 32);
    TextView title = new TextView(this);
    title.setText("Voice note waveform pipeline");
    title.setTextSize(24);
    waveformView = new WaveformBarsView(this);
    status = new TextView(this);
    status.setText("Ready");

    Button generate = button("Generate waveform", () -> {
      try {
        owner.generateWaveform(fullScaleSamples(), 2_000_000L);
      } catch (JSONException error) {
        fail(error);
      }
    });
    Button upload = button("Prepare upload", () -> {
      try {
        owner.startUploadGraph();
        owner.releaseHeldWaveform(fullScaleSamples(), 2_000_000L);
      } catch (JSONException error) {
        fail(error);
      }
    });
    Button render = button("Render waveform", () -> {
      try {
        owner.requestRenderableWaveform(fullScaleSamples(), 2_000_000L);
      } catch (JSONException error) {
        fail(error);
      }
    });
    Button send = button("Send pointer", () -> {
      try {
        owner.serializeOutgoingPointer();
      } catch (JSONException error) {
        fail(error);
      }
    });

    page.addView(title);
    page.addView(waveformView);
    page.addView(generate);
    page.addView(upload);
    page.addView(render);
    page.addView(send);
    page.addView(status);
    setContentView(page);
  }

  public void prepare(JSONObject given) throws JSONException {
    owner.mount(given);
    syncSurface();
  }

  public WaveformPageOwner owner() { return owner; }

  public String pageOwnerId() { return "VoiceWaveformActivity:" + System.identityHashCode(this); }

  public void syncSurface() throws JSONException {
    JSONObject snapshot = owner.snapshot();
    status.setText(snapshot.optJSONObject("state").toString());
    waveformView.setWaveform(snapshot.optJSONObject("state").optJSONArray("renderWaveform"));
  }

  private Button button(String label, View.OnClickListener action) {
    Button button = new Button(this);
    button.setText(label);
    button.setOnClickListener(action);
    return button;
  }

  private void fail(JSONException error) {
    status.setText(error.getMessage());
  }

  private static int[] fullScaleSamples() {
    int[] samples = new int[100];
    java.util.Arrays.fill(samples, 32767);
    return samples;
  }

  /** Draws the bars the page owner produced, at the fixed bar count the view renders. */
  static final class WaveformBarsView extends View {
    private final Paint paint = new Paint(Paint.ANTI_ALIAS_FLAG);
    private JSONArray bars = new JSONArray();

    WaveformBarsView(Context context) {
      super(context);
      paint.setColor(Color.parseColor("#3b7dd8"));
      setMinimumHeight(Math.round(96 * getResources().getDisplayMetrics().density));
    }

    void setWaveform(JSONArray waveform) {
      bars = waveform == null ? new JSONArray() : waveform;
      invalidate();
    }

    @Override protected void onDraw(Canvas canvas) {
      super.onDraw(canvas);
      int count = bars.length();
      if (count == 0) {
        return;
      }
      float width = getWidth() / (float) count;
      float height = getHeight();
      for (int i = 0; i < count; i++) {
        double magnitude = Math.max(0, Math.min(1, bars.optDouble(i, 0d)));
        float barHeight = (float) (magnitude * height);
        canvas.drawRect(i * width, height - barHeight, (i + 1) * width, height, paint);
      }
    }
  }
}

