    trace.effect("exportAttachment", attachmentId);
    exportedBackup = backupCodec.export(attachmentId, record);
    Json.put(state, "exportedFilePointer", exportedRow(attachment, record));

    store.clear();
    trace.effect("restoreAttachment", attachmentId);
    WaveformRecord restored = backupCodec.restore(exportedBackup, attachmentId);
