    if (restored != null && restored.isRenderable()) {
      Json.put(state, "result", "success");
      publishRender(restored);
      publishRecord(restored);
    } else {
      Json.put(state, "result", "error");
      Json.put(state, "reason", "restore_failed");
    }
    Json.put(state, "renderAfterRestore", renderResult(restored));
  }

